'use strict';
P.Systems={
spawn(dt){const s=P.state;s.spawn-=dt;if(s.spawn<=0&&s.enemies.length<P.Data.arena.enemyCap){s.enemies.push(P.Entities.enemy());s.spawn=Math.max(.24,.95-s.elapsed*.0023)}if(s.elapsed>=P.Data.arena.duration&&!s.bossSpawned){s.bossSpawned=true;s.enemies.push(P.Entities.enemy(true))}},
move(dt){const s=P.state,p=s.player,input=P.Core.direction(),length=Math.max(1,Math.hypot(input.x,input.y));p.inv=Math.max(0,p.inv-dt);const old={x:p.x,y:p.y};p.x+=input.x/length*p.speed*dt;p.y+=input.y/length*p.speed*dt;P.World.collide(p,old);
for(const e of s.enemies){const dx=p.x-e.x,dy=p.y-e.y,d=Math.hypot(dx,dy)||1;e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt;e.hit=Math.max(0,e.hit-dt);if(d<e.r+16&&p.inv<=0){p.hp=Math.max(0,p.hp-(e.boss?25:10));p.inv=.7;P.Entities.burst(p.x,p.y,'#ff8e7d');if(p.hp<=0){P.Game.finish(false);return}}}},
collect(dt){const s=P.state,p=s.player;for(const g of s.gems){const dx=p.x-g.x,dy=p.y-g.y,d=Math.hypot(dx,dy);if(d<p.magnet){g.x+=dx*Math.min(1,dt*9);g.y+=dy*Math.min(1,dt*9)}if(d<20){s.xp+=g.value;g.dead=true}}s.gems=s.gems.filter(g=>!g.dead);if(s.gems.length>500)s.gems.splice(0,s.gems.length-500);for(const e of s.effects){e.life-=dt;if(e.kind==='spark'){e.x+=e.vx*dt;e.y+=e.vy*dt}}s.effects=s.effects.filter(e=>e.life>0);if(s.xp>=s.need)this.levelup()},
levelup(){const s=P.state;s.xp-=s.need;s.level++;s.need=Math.round(s.need*1.3+2);s.mode='upgrade';const pool=[...P.Data.upgrades];for(let i=pool.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}P.UI.show('¡Te hiciste tendencia!','NIVEL '+s.level+' · Elige una mejora',pool.slice(0,3).map(u=>({title:u.title,description:u.description,action:()=>{u.apply(s.player);s.mode='play';P.$('#overlay').hidden=true;P.UI.hud();if(s.xp>=s.need)this.levelup()}})))}
};